mapper.select:
SELECT n.id, n.project_id, n.version, n.acceptance_time, b.id AS binding_id, b.source_owner, b.source_key
FROM
proj_project_stage nproj_project_task n
INNER JOIN proj_project p ON p.id = n.project_id AND p.tenant_id = n.tenant_id
LEFT JOIN proj_payment_acceptance_binding b ON b.tenant_id = n.tenant_id AND b.node_id = n.id AND b.node_type = #{query.nodeType}
WHERE n.tenant_id = #{query.tenantId} AND p.contract_no = #{query.contractNo}
  AND p.deleted = 0 AND n.deleted = 0 AND p.lifecycle_status = 'ACTIVE'
AND n.stage_code = #{query.nodeCode}AND n.task_code = #{query.nodeCode}
ORDER BY p.id, n.id
FOR UPDATE
